      "name": "Technical Skills & Code Quality",
      "description": "Assesses proficiency in programming languages, frameworks, coding standards, testing, and maintainability.",
      "levels": {
        "1": "Frequently produces buggy or poorly structured code. Ignores established best practices and coding standards. Requires extensive code review and rework.",
        "2": "Produces functional code with occasional quality issues. Follows basic standards but lacks consistency. Requires moderate review and guidance.",
        "3": "Consistently writes clean, maintainable, and well-tested code. Adheres to team standards and best practices. Requires minimal review.",
        "4": "Writes highly optimized, scalable, and robust code. Proactively refactors legacy systems and mentors peers on coding best practices.",
        "5": "Sets technical benchmarks for the organization. Introduces innovative patterns and tools that significantly elevate code quality across teams."
      }
    },
    {
      "category_id": "problem_solving",
      "name": "Problem Solving & Architecture",
      "description": "Evaluates ability to analyze complex issues, design scalable solutions, and make sound technical trade-offs.",
      "levels": {
        "1": "Struggles with debugging and complex problems. Relies heavily on others for solutions. Makes poor architectural decisions without considering trade-offs.",
        "2": "Solves routine technical issues independently. Needs guidance on system design and scalability. Occasionally overlooks edge cases.",
        "3": "Independently diagnoses and resolves complex issues. Designs practical, scalable solutions with clear consideration of trade-offs and constraints.",
        "4": "Tackles ambiguous, high-complexity challenges. Designs robust, future-proof architectures. Anticipates failure modes and implements resilient systems.",
        "5": "Architects enterprise-level solutions that drive strategic initiatives. Solves novel, industry-level problems and establishes technical direction."
      }
    },
    {
      "category_id": "collaboration",
      "name": "Collaboration & Communication",
      "description": "Measures effectiveness in teamwork, cross-functional communication, documentation, and knowledge sharing.",
      "levels": {
        "1": "Communicates poorly or inconsistently. Resists feedback. Works in silos and creates friction within the team.",
        "2": "Provides basic updates. Accepts feedback inconsistently. Limited engagement with cross-functional partners.",
        "3": "Communicates clearly and proactively. Collaborates effectively across teams. Gives and receives constructive feedback. Maintains adequate documentation.",
        "4": "Excels at translating technical concepts for non-technical stakeholders. Actively mentors peers. Drives team alignment and fosters a collaborative culture.",
        "5": "Inspires and unifies teams across the organization. Resolves conflicts diplomatically. Elevates communication standards and team dynamics significantly."
      }
    },
    {
      "category_id": "ownership",
      "name": "Ownership & Initiative",
      "description": "Assesses accountability, proactivity, project management, and commitment to delivering results.",
      "levels": {
        "1": "Waits for explicit direction. Avoids responsibility. Frequently misses deadlines without communication or mitigation.",
        "2": "Takes ownership of assigned tasks. Occasionally proactive. Needs reminders to track progress and communicate blockers.",
        "3": "Owns features or components end-to-end. Proactively identifies risks and solutions. Reliably meets commitments and deadlines.",
        "4": "Drives projects beyond initial scope. Anticipates team/organizational needs. Improves processes and takes calculated technical risks.",
        "5": "Champions high-impact initiatives. Transforms workflows and drives cultural change. Consistently delivers exceptional results with minimal oversight."
      }
    },
    {
      "category_id": "delivery",
      "name": "Delivery & Impact",
      "description": "Evaluates consistency of output, alignment with business goals, and measurable contribution to team/company success.",
      "levels": {
        "1": "Frequently misses deadlines. Output requires significant rework. Minimal or negative impact on team objectives.",
        "2": "Meets most deadlines with supervision. Moderate impact. Occasional misalignment with priorities or quality expectations.",
        "3": "Consistently delivers high-quality work on time. Clear, positive impact on sprint/quarterly goals. Aligns well with business priorities.",
        "4": "Accelerates delivery through process optimization. Produces measurable business/technical impact. Frequently exceeds targets.",
        "5": "Drives transformative results that scale across the organization. Consistently delivers exceptional value and sets new performance benchmarks."
      }
    },
    {
      "category_id": "growth",
      "name": "Continuous Learning & Growth",
      "description": "Measures commitment to skill development, adaptability, and contribution to team knowledge.",
      "levels": {
        "1": "Resists learning new technologies or methodologies. Ignores feedback. Skills remain stagnant.",
        "2": "Learns when explicitly required. Basic skill development. Limited knowledge sharing with the team.",
        "3": "Actively pursues learning opportunities. Applies feedback effectively. Regularly shares knowledge and stays current with industry trends.",
        "4": "Proactively upskills and introduces new tools/practices to the team. Mentors others and drives technical growth initiatives.",
        "5": "Industry thought leader who continuously pushes technical boundaries. Transforms team capabilities through innovation and knowledge leadership."
      }
    }
  ],
  "usage_guidelines": {
    "scoring_method": "Rate each category on a scale of 1-5 based on documented evidence and observable behaviors over the review period.",
    "calibration": "Managers should calibrate scores with peers to ensure consistency and reduce bias.",
    "documentation": "Support each rating with specific examples, metrics, and feedback from stakeholders.",
    "development_planning": "Use lower scores to identify growth areas and higher scores to recognize strengths and plan career progression.",
    "review_frequency": "Recommended quarterly check-ins with a comprehensive annual evaluation."
  }
}

